import { useState } from "react";
import { ImageInput, Field } from "@/components/admin/articles/ArticleSubComponents";
import { useSiteSettings } from "@/components/site/AdSettingsContext";
import {
  Camera,
  Sparkles,
  Globe,
  Share2,
  Building2,
  Info,
  Check,
  RotateCcw,
} from "lucide-react";
import type { Row } from "./types";

interface ArticleMediaTabProps {
  row: Row;
  onChange: <K extends keyof Row>(field: K, value: Row[K]) => void;
}

export default function ArticleMediaTab({ row, onChange }: ArticleMediaTabProps) {
  const settings = useSiteSettings();
  const defaultSiteName = settings?.siteName || "Today Tripura";
  const activeCredit = row.imageCredit?.trim() || defaultSiteName;

  // Auto-sync Featured Image to Open Graph image if OG image was empty or matching previous featured image
  const handleFeaturedImageChange = (newUrl: string) => {
    const prevFeatured = row.featuredImage || "";
    onChange("featuredImage", newUrl);

    // If ogImage was empty, or was previously synced with the old featured image, auto-sync it!
    if (!row.ogImage || row.ogImage === prevFeatured) {
      onChange("ogImage", newUrl);
    }
  };

  const isCustomOg = Boolean(row.ogImage && row.featuredImage && row.ogImage !== row.featuredImage);

  // Auto-detect Bengali from title, content, or excerpt
  const isAutoBengali = /[\u0980-\u09FF]/.test(
    (row.title || "") + " " + (row.content || "") + " " + (row.excerpt || "")
  );

  const [langOverride, setLangOverride] = useState<"auto" | "bn" | "en">("auto");
  const isBengali = langOverride === "auto" ? isAutoBengali : langOverride === "bn";

  const PRESET_CAPTIONS = isBengali
    ? [
        { label: "প্রতীকী ছবি", value: "প্রতীকী ছবি" },
        { label: "ফাইল ছবি", value: "ফাইল ছবি" },
        { label: "ছবি: সংগৃহীত", value: "ছবি: সংগৃহীত" },
        { label: "ছবি: সোশ্যাল মিডিয়া", value: "ছবি: সোশ্যাল মিডিয়া" },
        { label: "নিজস্ব চিত্র", value: "নিজস্ব চিত্র" },
        { label: "সংগৃহীত", value: "সংগৃহীত" },
      ]
    : [
        { label: "Representative Image", value: "Representative Image" },
        { label: "File Photo", value: "File Photo" },
        { label: "Staff Photo", value: "Staff Photo" },
        { label: "Social Media Photo", value: "Social Media Photo" },
        { label: "Collected from Web", value: "Collected from Web" },
        { label: "Press Handout", value: "Press Handout" },
      ];

  const PRESET_CREDITS = isBengali
    ? [
        { label: defaultSiteName, value: defaultSiteName, icon: Building2, desc: "ওয়েবসাইট / নিউজরুম" },
        { label: "নিউজরুম ডেস্ক", value: "নিউজরুম ডেস্ক", icon: Camera, desc: "নিউজরুম স্টাফ" },
        { label: "সোশ্যাল মিডিয়া", value: "সোশ্যাল মিডিয়া", icon: Share2, desc: "সোশ্যাল মিডিয়া থেকে প্রাপ্ত" },
        { label: "ওয়েব থেকে সংগৃহীত", value: "ওয়েব থেকে সংগৃহীত", icon: Globe, desc: "অনলাইন উৎস" },
        { label: "এআই নির্মিত", value: "এআই নির্মিত", icon: Sparkles, desc: "কৃত্রিম বুদ্ধিমত্তা দ্বারা নির্মিত" },
      ]
    : [
        { label: defaultSiteName, value: defaultSiteName, icon: Building2, desc: "Website / Newsroom" },
        { label: "Newsroom Desk", value: "Newsroom Desk", icon: Camera, desc: "Staff Photographer" },
        { label: "Social Media", value: "Social Media", icon: Share2, desc: "Collected from Social Media" },
        { label: "Collected from Web", value: "Collected from Web", icon: Globe, desc: "Online Source" },
        { label: "AI Generated", value: "AI Generated", icon: Sparkles, desc: "Generated with AI" },
      ];

  return (
    <div className="space-y-5">
      {/* Featured Image Section */}
      <div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm space-y-5">
        <Field label="Featured Image">
          <ImageInput
            value={row.featuredImage}
            onChange={handleFeaturedImageChange}
            hint="Used as the hero image at the top of the post and default Open Graph image."
          />
        </Field>

        {/* Caption & Image Credit Sub-box */}
        <div className="rounded-lg border border-slate-200 bg-slate-50/70 p-4 space-y-4">
          <div className="flex items-center gap-2 border-b border-slate-200/80 pb-2.5">
            <Camera className="h-4 w-4 text-slate-600" />
            <span className="text-xs font-bold uppercase tracking-wider text-slate-800">
              Featured Image Caption &amp; Source Credit
            </span>
            <span className="ml-auto text-[11px] text-slate-400">
              Shown beneath the photo on the article page
            </span>
          </div>

          {/* Image Caption Input & Presets */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between">
              <label
                htmlFor="article-image-caption"
                className="block text-xs font-semibold text-slate-700"
              >
                Photo Caption / Description
              </label>
              <div className="flex items-center gap-1 text-[11px] text-slate-500">
                <span className="text-[10px] uppercase font-bold text-slate-400">Language:</span>
                <button
                  type="button"
                  onClick={() => setLangOverride(langOverride === "bn" ? "en" : "bn")}
                  className="rounded border border-slate-200 bg-white px-2 py-0.5 font-medium text-slate-700 hover:bg-slate-100 transition-colors cursor-pointer"
                  title="Toggle preset language between Bengali and English"
                >
                  {isBengali ? "🇧🇩 বাংলা (Bengali)" : "🇬🇧 English"}
                </button>
              </div>
            </div>

            {/* Quick Caption Preset Chips */}
            <div className="flex flex-wrap items-center gap-1.5 pb-1">
              <span className="text-[10px] uppercase font-bold text-slate-500 mr-0.5">
                Quick Defaults:
              </span>
              {PRESET_CAPTIONS.map((preset) => {
                const isSelected = (row.imageCaption || "").trim() === preset.value;
                return (
                  <button
                    key={preset.value}
                    type="button"
                    onClick={() => onChange("imageCaption", preset.value)}
                    className={`inline-flex items-center gap-1 rounded-md px-2.5 py-0.5 text-[11px] font-medium transition cursor-pointer border ${
                      isSelected
                        ? "border-slate-900 bg-slate-900 text-white shadow-xs"
                        : "border-slate-200 bg-white text-slate-700 hover:bg-slate-100 hover:border-slate-300"
                    }`}
                  >
                    <span>{preset.label}</span>
                    {isSelected && <Check className="h-2.5 w-2.5 stroke-[3]" />}
                  </button>
                );
              })}
              {row.imageCaption && (
                <button
                  type="button"
                  onClick={() => onChange("imageCaption", "")}
                  className="text-[11px] text-slate-400 hover:text-red-500 transition-colors ml-1 underline cursor-pointer"
                >
                  Clear
                </button>
              )}
            </div>

            <input
              id="article-image-caption"
              name="imageCaption"
              type="text"
              value={row.imageCaption || ""}
              onChange={(e) => onChange("imageCaption", e.target.value)}
              placeholder={
                isBengali
                  ? "যেমন: প্রতীকী ছবি, ফাইল ছবি, বা নিজস্ব ক্যাপশন লিখুন..."
                  : "e.g. Representative Image, File Photo, or enter custom caption..."
              }
              className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-xs text-slate-900 placeholder:text-slate-400 focus:border-slate-900 focus:outline-none"
            />
            <p className="text-[11px] text-slate-400">
              {isBengali
                ? "উপরের দ্রুত বিকল্প নির্বাচন করুন অথবা আপনার নিজস্ব ক্যাপশন লিখুন।"
                : "Select a quick preset above or type your own description."}
            </p>
          </div>

          {/* Image Source / Credit Field */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <label
                htmlFor="article-image-credit"
                className="block text-xs font-semibold text-slate-700"
              >
                Photo Source / Credit Name
              </label>
              <span className="text-[11px] text-slate-400">
                Default: <strong className="text-slate-600 font-medium">{defaultSiteName}</strong>
              </span>
            </div>

            {/* Quick Preset Buttons */}
            <div className="flex flex-wrap items-center gap-1.5">
              {PRESET_CREDITS.map((preset) => {
                const isSelected =
                  (row.imageCredit || "").toLowerCase() === preset.value.toLowerCase() ||
                  (!row.imageCredit && preset.value === defaultSiteName);
                const Icon = preset.icon;
                return (
                  <button
                    key={preset.value}
                    type="button"
                    onClick={() => onChange("imageCredit", preset.value)}
                    className={`inline-flex items-center gap-1.5 rounded-md px-2.5 py-1 text-[11px] font-medium transition cursor-pointer border ${
                      isSelected
                        ? "border-slate-900 bg-slate-900 text-white shadow-xs"
                        : "border-slate-200 bg-white text-slate-700 hover:bg-slate-100 hover:border-slate-300"
                    }`}
                    title={preset.desc}
                  >
                    <Icon className="h-3 w-3 shrink-0" />
                    <span>{preset.label}</span>
                    {isSelected && <Check className="h-2.5 w-2.5 stroke-[3]" />}
                  </button>
                );
              })}
            </div>

            {/* Custom Input for Source */}
            <div className="pt-1">
              <input
                id="article-image-credit"
                name="imageCredit"
                type="text"
                value={row.imageCredit || ""}
                onChange={(e) => onChange("imageCredit", e.target.value)}
                placeholder={`Custom source name (leave blank for default: ${defaultSiteName})...`}
                className="w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-xs text-slate-900 placeholder:text-slate-400 focus:border-slate-900 focus:outline-none"
              />
            </div>
          </div>

          {/* Live Preview Box */}
          <div className="rounded-md border border-amber-200/70 bg-amber-50/60 p-3 text-xs space-y-1">
            <span className="text-[10px] font-bold uppercase tracking-wider text-amber-800 flex items-center gap-1">
              <Info className="h-3 w-3 text-amber-600" /> Post View Preview
            </span>
            <div className="text-slate-600 italic">
              {row.imageCaption?.trim() ? (
                <span>{row.imageCaption.trim()}</span>
              ) : (
                <span className="text-slate-400 not-italic">(No caption entered)</span>
              )}
              <span className="mx-2 not-italic text-slate-300">|</span>
              <span className="not-italic font-bold uppercase tracking-wider text-slate-800">
                {activeCredit}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Open Graph Image Section */}
      <div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-slate-100 pb-3">
          <div>
            <div className="flex items-center gap-2">
              <Share2 className="h-4 w-4 text-indigo-600" />
              <span className="text-xs font-bold uppercase tracking-wider text-slate-800">
                Open Graph Image (Social Media Sharing)
              </span>
            </div>
            <p className="text-[11px] text-slate-500 mt-0.5">
              Image shown when shared on Facebook, WhatsApp, Telegram, or Twitter/X. Recommended: 1200×630 px.
            </p>
          </div>

          <div className="flex items-center gap-2">
            {isCustomOg ? (
              <button
                type="button"
                onClick={() => onChange("ogImage", row.featuredImage || "")}
                className="inline-flex items-center gap-1.5 rounded-md border border-slate-200 bg-slate-50 px-2.5 py-1 text-xs font-semibold text-slate-700 hover:bg-slate-100 hover:text-slate-900 transition cursor-pointer shadow-2xs"
                title="Reset Open Graph image to match Featured Image"
              >
                <RotateCcw className="h-3 w-3 text-slate-500" />
                <span>Reset to Featured Image</span>
              </button>
            ) : row.featuredImage ? (
              <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 border border-emerald-200 px-2.5 py-1 text-[11px] font-semibold text-emerald-700">
                <Check className="h-3 w-3 stroke-[3]" />
                Auto-Synced with Featured Image
              </span>
            ) : (
              <span className="text-[11px] text-slate-400 italic">
                (Add a Featured Image above to auto-populate)
              </span>
            )}
          </div>
        </div>

        <Field
          label={
            isCustomOg
              ? "Custom Open Graph Image (Active Override)"
              : "Open Graph Image (Defaults to Featured Image)"
          }
        >
          <ImageInput
            value={row.ogImage}
            onChange={(v) => onChange("ogImage", v)}
            fallbackValue={row.featuredImage}
            fallbackLabel="Auto: Featured Image"
            onResetToFallback={() => onChange("ogImage", row.featuredImage || "")}
            hint="Override only if you want a different custom banner when shared on social media. Recommended 1200×630."
          />
        </Field>
      </div>
    </div>
  );
}
